# Soal matematika menuntut satu kehati-hatian yang tidak ada pada bahasa: PENGECOHNYA
# HARUS HASIL HITUNGAN YANG SALAH, bukan angka acak. Murid yang memilih -19 pada soal
# -7 + 12 tidak sedang menebak; ia menjumlahkan nilai mutlaknya lalu mengambil tanda dari
# bilangan pertama. Pengecoh acak membuat jawaban benar bisa ditebak lewat eliminasi, dan
# membuang seluruh nilai diagnostiknya.
