# GELOMBANG 10: MATEMATIKA KELAS 8-9
# ==========================================================================
# Kelas 8 dan 9 memindahkan matematika dari menghitung ke MEMBUKTIKAN: pangkat punya
# sifat, akar punya bentuk paling sederhana, segitiga siku-siku punya hubungan yang
# berlaku selalu. Miskonsepsi di jenjang ini hampir seluruhnya berupa ATURAN YANG
# DIPUKUL RATA — pangkat ikut dikalikan saat basisnya dikalikan, akar dijumlahkan
# seperti bilangan biasa, satuan luas dipakai untuk volume. Pengecoh di bawah adalah
# hasil dari aturan-pukul-rata itu, bukan angka acak.
